#[path = "solution.rs"]
mod solution;

define_record! {
    #[derive(Clone, Debug, PartialEq)]
    pub struct Example {
        pub first: u32,
        pub label: String,
    }
}

define_record! {
    #[derive(Debug, PartialEq)]
    pub(crate) struct MixedVisibility {
        pub visible: bool,
        hidden: Option<i64>
    }
}

define_record! {
    #[derive(Debug, PartialEq)]
    struct Empty {}
}

#[test]
fn reports_field_names_in_declaration_order() {
    assert_eq!(Example::field_names(), &["first", "label"]);
    assert_eq!(MixedVisibility::field_names(), &["visible", "hidden"]);
}

#[test]
fn supports_empty_records() {
    assert_eq!(Empty::field_names(), &[] as &[&str]);
}

#[test]
fn emitted_struct_preserves_requested_fields_and_derives() {
    let record = Example { first: 42, label: String::from("stable") };
    let cloned = record.clone();
    assert_eq!(cloned, record);
    assert_eq!(record.first, 42);
    assert_eq!(record.label, "stable");
}

#[test]
fn supports_field_visibility_and_optional_trailing_comma() {
    let record = MixedVisibility { visible: true, hidden: Some(-7) };
    assert!(record.visible);
    assert_eq!(record.hidden, Some(-7));
}

#[test]
fn field_name_slice_is_stable_and_static() {
    let first: &'static [&'static str] = Example::field_names();
    let second = Example::field_names();
    assert_eq!(first, second);
}

